"""Entity 6, Recommendations (personalised, generated by the AI module)."""

from datetime import UTC, datetime

from sqlalchemy import Boolean, DateTime, Float, ForeignKey, Integer, String, Text
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.database import Base


class Recommendation(Base):
    __tablename__ = "recommendations"

    recommendation_id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    customer_id: Mapped[str] = mapped_column(
        String(20), ForeignKey("customers.customer_id", ondelete="CASCADE"),
        nullable=False, index=True,
    )

    title: Mapped[str] = mapped_column(String(200), nullable=False)
    description: Mapped[str] = mapped_column(Text, nullable=False)
    estimated_savings: Mapped[float] = mapped_column(Float, default=0.0)

    # 'High' | 'Medium' | 'Low'
    priority: Mapped[str] = mapped_column(String(20), default="Medium", nullable=False)

    # lucide-react icon name used by the frontend
    icon: Mapped[str] = mapped_column(String(60), default="Lightbulb")
    completed: Mapped[bool] = mapped_column(Boolean, default=False)

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=lambda: datetime.now(UTC)
    )

    customer = relationship("Customer", back_populates="recommendations")

    def __repr__(self) -> str:  # pragma: no cover
        return f"<Recommendation {self.recommendation_id} {self.title!r}>"
